            "statement": "AI 기능(Rovo) 채택이 'AI가 SaaS 수요를 대체한다'는 시장 우려를 반박하는 근거로 작용했다. Rovo 지원 액션이 QoQ +50% 증가했고 Rovo 이용자는 비이용자 대비 Jira 작업 처리량이 20% 많고 Confluence 페이지 생성·편집이 25% 많다.",
