            "statement": "영업이익률이 직전 분기 -41.4%에서 -30.6%로 개선되며 마진 트렌드가 우호적으로 전환됐다. 다만 순손실은 YoY -271.9%로 오히려 확대돼(1차 자료 기준) 영업외 손익 항목의 영향이 컸던 것으로 보이며, 영업손익 개선과 순손실 확대가 동시에 나타난 점은 이익의 질(quality of earnings) 측면에서 확인이 필요하다.",
