        "ticker": "MLAB",
        "company": "Mesa Laboratories는 생명과학·바이오제약·헬스케어 및 산업용 멸균·오염관리 분야에 품질관리용 계측기기·소모품·서비스를 공급하며, Calibration Solutions·Biopharmaceutical Development·Sterilization & Disinfection Control(SDC) 사업부로 구성된다. 최근 분기(2026-06-30 마감, FY2027 Q1) 매출은 6,013.8만 달러(YoY +1.0%)로 Calibration Solutions·Biopharma Dev 부문 유기성장 회복이 견인했고 SDC는 배송 지연 이슈로 역성장 중이다. 영업이익률은 직전 분기 4.3%에서 11.7%로 급반등했으나 GAAP 순이익은 YoY -40.3% 감소하는 등 이익의 질에 변동성이 남아있는 국면이다.",
        "lead": "MLAB은 RS 상위 1M 1.8%/3M 7.7%/6M 9.6%로 스크리닝 상위권에 오른 소형 과학계측기 업체로, 최근 1개월 14.7%·3개월 28.1%·6개월 47.84% 상승하며 52주 고점 대비 91.54%(200일선 대비 +27.12% 이격)까지 근접했다. 순부채비율이 1.85배로 축소되고 영업현금흐름이 1,470만 달러로 증가하며 현금창출력과 재무구조가 동시에 개선되었다.",
