        "leadOriginal": "MLAB은 RS 상위 1M 1.8%/3M 7.7%/6M 9.6%로 스크리닝 상위권에 오른 소형 과학계측기 업체로, 최근 1개월 14.7%·3개월 28.1%·6개월 47.84% 상승하며 52주 고점 대비 91.54%(200일선 대비 +27.12% 이격)까지 근접했다. 상승의 핵심은 2026-08-17 발표된 FY2027 Q1(2026-06-30 마감) 실적에서 매출 YoY +1.0%로 유기성장이 플러스 전환되고 영업이익률이 직전 분기 4.3%에서 11.7%로 급반등한 데 있다. 다만 GAAP 순이익은 여전히 YoY -40.3% 감소했고 FY2027 가이던스는 11월 2분기 실적 발표 시로 유보돼 있다.",
