            "statement": "2026년 8월 12일 발표된 2분기 실적에서 순손실이 확대됐다고 보도됐다. SEC 제출 분기 재무제표 기준 최근 분기(2026-03-31 마감) 영업손실은 -5,225,253달러(YoY -62.2%), 순손실은 -3,893,050달러(YoY -48.3%)로 전년 대비 손실폭이 커졌고, 해당 분기 매출은 0달러로 4개 분기 연속 무매출 상태다. 상업화 전 단계에서 손실이 확대되는 국면이므로 추가 자금조달에 따른 희석 리스크를 배제할 수 없다.",
